CREATE COLUMN TABLE "Pricetrack" AS ( SELECT DISTINCT T0."ItemCode",C."UomCode",A."CodeBars", T1."PriceList", T2."ListName", t1."Currency", T1."Price", T0."UpdateDate", T1."LogInstanc" ,N."U_NAME" as "USERNAME"     FROM AITM T0          INNER JOIN AIT1 T1 ON T0."ItemCode" = T1."ItemCode" AND t0."LogInstanc" = t1."LogInstanc"          LEFT OUTER JOIN AIT1 T3 ON T1."ItemCode" = T3."ItemCode" AND t1."PriceList" = T3."PriceList" AND              t1."LogInstanc" > t3."LogInstanc"          INNER JOIN OPLN T2 ON T1."PriceList" = T2."ListNum"         inner join OITM A on T1."ItemCode"=A."ItemCode" INNER JOIN OUSR N  ON A."UserSign" = N."USERID"  inner join  UGP1 B on A."UgpEntry"=B."UgpEntry"  INNER JOIN OUOM C ON B."UomEntry" = C."UomEntry"     WHERE (t1."Price" <> t3."Price")      UNION     SELECT DISTINCT T0."ItemCode", C."UomCode",A."CodeBars",T1."PriceList", T2."ListName", t1."Currency", T1."Price", T0."UpdateDate", T1."LogInstanc" ,N."U_NAME"  as "USERNAME"     FROM AITM T0          INNER JOIN AIT1 T1 ON T0."ItemCode" = T1."ItemCode" AND t0."LogInstanc" = t1."LogInstanc"          LEFT OUTER JOIN AIT1 T3 ON T1."ItemCode" = T3."ItemCode" AND t1."PriceList" = T3."PriceList" AND              t1."LogInstanc" > t3."LogInstanc"          INNER JOIN OPLN T2 ON T1."PriceList" = T2."ListNum"         inner join OITM A on T1."ItemCode"=A."ItemCode" INNER JOIN OUSR N ON A."UserSign" = N."USERID"  inner join  UGP1 B on A."UgpEntry"=B."UgpEntry"  INNER JOIN OUOM C ON B."UomEntry" = C."UomEntry"     WHERE (t1."Price" = t3."Price" AND T1."Currency" <> T3."Currency")      UNION     SELECT DISTINCT T5."ItemCode",C."UomCode",A."CodeBars", T5."PriceList", T2."ListName", t5."Currency", T5."Price", '', T5."LogInstanc" ,N."U_NAME"  as "USERNAME"     FROM AITM T0          INNER JOIN AIT1 T1 ON T0."ItemCode" = T1."ItemCode" AND t0."LogInstanc" = t1."LogInstanc"          LEFT OUTER JOIN AIT1 T3 ON T1."ItemCode" = T3."ItemCode" AND t1."PriceList" = T3."PriceList" AND              t1."LogInstanc" > t3."LogInstanc"          RIGHT OUTER JOIN OPLN T4 ON T1."PriceList" <> T4."ListNum"          INNER JOIN ITM1 T5 ON T4."ListNum" = T5."PriceList"          INNER JOIN OPLN T2 ON T1."PriceList" = T2."ListNum"          inner join OITM A on T5."ItemCode"=A."ItemCode" INNER JOIN OUSR N ON A."UserSign" = N."USERID"  inner join  UGP1 B on A."UgpEntry"=B."UgpEntry"  INNER JOIN OUOM C ON B."UomEntry" = C."UomEntry"      WHERE T4.BASE_NUM <> T4."ListNum" AND T5."Price" <> 0      EXCEPT      SELECT DISTINCT T0."ItemCode",C."UomCode",A."CodeBars", T1."PriceList", T2."ListName", t1."Currency", T1."Price", T0."UpdateDate", T1."LogInstanc" ,N."U_NAME"  as "USERNAME"     FROM AITM T0          INNER JOIN AIT1 T1 ON T0."ItemCode" = T1."ItemCode" AND t0."LogInstanc" = t1."LogInstanc"          LEFT OUTER JOIN AIT1 T3 ON T1."ItemCode" = T3."ItemCode" AND t1."PriceList" = T3."PriceList" AND              t1."LogInstanc" > t3."LogInstanc"          INNER JOIN OPLN T2 ON T1."PriceList" = T2."ListNum"         inner join OITM A on T1."ItemCode"=A."ItemCode" INNER JOIN OUSR N  ON A."UserSign" = N."USERID"  inner join  UGP1 B on A."UgpEntry"=B."UgpEntry"  INNER JOIN OUOM C ON B."UomEntry" = C."UomEntry"     WHERE t1."Price" = t3."Price" AND      t1."Currency" = T3."Currency");       select     ss."ItemCode", (SELECT T1."ItmsGrpNam" FROM OITM T0  INNER JOIN OITB T1 ON T0."ItmsGrpCod" = T1."ItmsGrpCod" WHERE T0."ItemCode" =ss."ItemCode") "Item Group",  ss."UomCode",  ss."CodeBars",  ss."PriceList",  (select   "ItemName"   from OITM A   where A."ItemCode"=ss."ItemCode") "Name",  (SELECT distinct    T0."Price"   FROM ITM1 T0   WHERE T0."PriceList" =ss."PriceList"   and T0."ItemCode" =ss."ItemCode") "RSP",  ss."Price" "Old RSP",  ss."UpdateDate", ss."USERNAME"      from (SELECT   *   FROM "Pricetrack")ss  where "LogInstanc" in (SELECT   ("LogInstanc")   FROM "Pricetrack"   where "ItemCode"=ss."ItemCode" and "UomCode"=ss."UomCode" and "PriceList"=ss."PriceList")  ---and  ss."ItemCode"='0100020908'  and ss."PriceList" ='1' and ss."UpdateDate"=CURRENT_DATE   ORDER BY "ItemCode",   "PriceList",   "LogInstanc"  ; DROP TABLE "Pricetrack";
